def fold_and(xs: list) -> bool:
    result = True
    for x in xs:
        result = result and x
        if not result:
            return False
    return result

def balanced_and(xs: list) -> bool:
    n = len(xs)
    if n == 0: return True
    if n == 1: return xs[0]
    mid = n // 2
    return balanced_and(xs[:mid]) and balanced_and(xs[mid:])

def canonical_and(op, xs, method='balanced'):
    if method == 'sequential': return op(fold_and(xs))
    elif method == 'balanced': return op(balanced_and(xs))
    elif method == 'dedup': return op(fold_and(list(set(xs))))
